29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
68	     * domain containing at least one dot, with no whitespace in any part.
69	     */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
122	            assignHousehold(owner, ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
123	        } else {
124	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
125	        }
126	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
127	        rejectDuplicateTelephone(telephone);
128	        owner.setTelephone(telephone);
129	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
130	        if (owner.getRegistrationDate() == null) {
131	            owner.setRegistrationDate(LocalDate.now());
132	        }
133	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
144	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
145	        if (currentOwner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        currentOwner.setAddress(ownerFieldsDto.getAddress());
149	        currentOwner.setCity(ownerFieldsDto.getCity());
150	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
151	        currentOwner.setLastName(ownerFieldsDto.getLastName());
152	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
153	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        this.clinicService.saveOwner(currentOwner);
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        this.clinicService.deleteOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
237	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
238	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
239	     *
240	     * @param ownerFieldsDto the submitted owner fields
241	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
242	     *                                     name of every offending field
243	     */
244	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
245	        List<String> missingFields = new ArrayList<>();
246	        if (isBlank(ownerFieldsDto.getFirstName())) {
247	            missingFields.add("firstName");
248	        }
249	        if (isBlank(ownerFieldsDto.getLastName())) {
250	            missingFields.add("lastName");
251	        }
252	        if (isBlank(ownerFieldsDto.getAddress())) {
253	            missingFields.add("address");
254	        }
255	        if (isBlank(ownerFieldsDto.getCity())) {
256	            missingFields.add("city");
257	        }
258	        if (isBlank(ownerFieldsDto.getTelephone())) {
259	            missingFields.add("telephone");
260	        }
261	        if (!missingFields.isEmpty()) {
262	            throw new InvalidOwnerFieldsException(missingFields);
263	        }
264	    }
265	
266	    private boolean isBlank(String value) {
267	        return value == null || value.isBlank();
268	    }
269	
270	    /**
271	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
272	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
273	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
274	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
275	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
276	     *
277	     * @param telephone the raw telephone value submitted by the client
278	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
279	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
280	     *                                     400 response
281	     */
282	    private String normalizeTelephone(String telephone) {
283	        String e164 = toE164(telephone);
284	        if (e164 == null) {
285	            throw new InvalidOwnerFieldsException(List.of("telephone"));
286	        }
287	        return e164;
288	    }
289	
290	    /**
291	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
292	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
293	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
294	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
295	     *
296	     * @param telephone the raw telephone value, possibly {@code null}
297	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
298	     */
299	    private String toE164(String telephone) {
300	        if (telephone == null) {
301	            return null;
302	        }
303	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
304	        boolean hasPlus = cleaned.startsWith("+");
305	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
306	        String nationalSignificant = hasPlus
307	            ? digits
308	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
309	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
310	            return null;
311	        }
312	        return "+" + nationalSignificant;
313	    }
314	
315	    /**
316	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
317	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
318	     * returned value is that address lower-cased.
319	     *
320	     * @param email the raw email value submitted by the client, or {@code null} if omitted
321	     * @return the lower-cased email, or {@code null} if none was supplied
322	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
323	     *                                     yielding a 400 response
324	     */
325	    private String normalizeEmail(String email) {
326	        if (email == null) {
327	            return null;
328	        }
329	        if (!EMAIL_PATTERN.matcher(email).matches()) {
330	            throw new InvalidOwnerFieldsException(List.of("email"));
331	        }
332	        return email.toLowerCase(Locale.ROOT);
333	    }
334	
335	    /**
336	     * Builds the owner's {@code customerCode}, formatted {@code '<LAST3>-<NNNN>'}. {@code LAST3} is
337	     * the upper-cased first three letters of the last name, and {@code NNNN} is a global 4-digit
338	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
339	     *
340	     * @param lastName the owner's last name
341	     * @return the formatted customer code
342	     */
343	    private String generateCustomerCode(String lastName) {
344	        String letters = lastName.replaceAll("[^\\p{L}]", "");
345	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
346	        int sequence = this.clinicService.findAllOwners().size() + 1;
347	        return String.format("%s-%04d", last3, sequence);
348	    }
349	
350	    /**
351	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
352	     * telephones are converted to E.164 here as well so the comparison is independent of the format
353	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
354	     * ignored rather than matched.
355	     *
356	     * @param telephone the E.164 telephone of the owner being created
357	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
358	     *                                          yielding a 409 Conflict response
359	     */
360	    private void rejectDuplicateTelephone(String telephone) {
361	        boolean inUse = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getTelephone)
363	            .map(this::toE164)
364	            .anyMatch(telephone::equals);
365	        if (inUse) {
366	            throw new DuplicateOwnerTelephoneException(telephone);
367	        }
368	    }
369	
370	    /**
371	     * Rejects creation of an owner whose last name and address both match an existing owner's,
372	     * which marks them as belonging to the same household. Both the last name and the address are
373	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
374	     * that differ only in letter case or spacing are still treated as a match.
375	     *
376	     * @param lastName the last name of the owner being created
377	     * @param address  the address of the owner being created
378	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
379	     *                                          address, yielding a 409 Conflict response
380	     */
381	    private void rejectDuplicateHousehold(String lastName, String address) {
382	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
383	            throw new DuplicateOwnerHouseholdException(lastName, address);
384	        }
385	    }
386	
387	    /**
388	     * Finds every existing owner belonging to the household identified by the given last name and
389	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
390	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
391	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
392	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
393	     * and {@link #assignHousehold}.
394	     *
395	     * @param lastName the last name of the owner being created
396	     * @param address  the address of the owner being created
397	     * @return the existing owners in that household, or an empty list if there are none
398	     */
399	    private List<Owner> findHouseholdMembers(String lastName, String address) {
400	        String normalizedLastName = normalizeForComparison(lastName);
401	        String normalizedAddress = normalizeForComparison(address);
402	        return this.clinicService.findAllOwners().stream()
403	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
404	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
405	            .toList();
406	    }
407	
408	    /**
409	     * Enrolls a newly created owner into the household of any existing owner that shares its last
410	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
411	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
412	     * whitespace. When at least one such owner already exists, every member of the household — the
413	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
414	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
415	     * and address is created and back-filled onto the existing members. When no owner yet lives at
416	     * that address under the same last name no identifier is assigned and the owner is created alone.
417	     *
418	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
419	     * @param lastName the last name of the owner being created
420	     * @param address  the address of the owner being created
421	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
422	     */
423	    private String assignHousehold(Owner newOwner, String lastName, String address) {
424	        List<Owner> members = findHouseholdMembers(lastName, address);
425	        if (members.isEmpty()) {
426	            return null;
427	        }
428	        String householdId = members.stream()
429	            .map(Owner::getHouseholdId)
430	            .filter(existing -> existing != null && !existing.isBlank())
431	            .findFirst()
432	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeForComparison(address)));
433	        for (Owner member : members) {
434	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
435	                member.setHouseholdId(householdId);
436	                this.clinicService.saveOwner(member);
437	            }
438	        }
439	        newOwner.setHouseholdId(householdId);
440	        return householdId;
441	    }
442	
443	    /**
444	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
445	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
446	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
447	     * same identifier, so members of one household share a single value.
448	     *
449	     * @param normalizedLastName the household's last name, already normalized for comparison
450	     * @param normalizedAddress  the household's address, already normalized for comparison
451	     * @return the derived household identifier
452	     */
453	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
454	        try {
455	            byte[] digest = MessageDigest.getInstance("SHA-256")
456	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
457	            StringBuilder hex = new StringBuilder(digest.length * 2);
458	            for (byte b : digest) {
459	                hex.append(String.format("%02x", b));
460	            }
461	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
462	        } catch (NoSuchAlgorithmException e) {
463	            throw new IllegalStateException("SHA-256 algorithm not available", e);
464	        }
465	    }
466	
467	    /**
468	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
469	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
470	     * the result is lower-cased.
471	     *
472	     * @param value the value to normalize, possibly {@code null}
473	     * @return the normalized value, or an empty string if {@code value} is {@code null}
474	     */
475	    private String normalizeForComparison(String value) {
476	        if (value == null) {
477	            return "";
478	        }
479	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
480	    }
481	}
