16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
64	    private Set<Pet> pets;
65	
66	    public String getAddress() {
67	        return this.address;
68	    }
69	
70	    public void setAddress(String address) {
71	        this.address = address;
72	    }
73	
74	    public String getCity() {
75	        return this.city;
76	    }
77	
78	    public void setCity(String city) {
79	        this.city = city;
80	    }
81	
82	    public String getTelephone() {
83	        return this.telephone;
84	    }
85	
86	    public void setTelephone(String telephone) {
87	        this.telephone = telephone;
88	    }
89	
90	    public String getEmail() {
91	        return this.email;
92	    }
93	
94	    public void setEmail(String email) {
95	        this.email = email;
96	    }
97	
98	    public LocalDate getRegistrationDate() {
99	        return this.registrationDate;
100	    }
101	
102	    public void setRegistrationDate(LocalDate registrationDate) {
103	        this.registrationDate = registrationDate;
104	    }
105	
106	    public String getCustomerCode() {
107	        return this.customerCode;
108	    }
109	
110	    public void setCustomerCode(String customerCode) {
111	        this.customerCode = customerCode;
112	    }
113	
114	    public String getHouseholdId() {
115	        return this.householdId;
116	    }
117	
118	    public void setHouseholdId(String householdId) {
119	        this.householdId = householdId;
120	    }
121	
122	    /**
123	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
124	     */
125	    @Transient
126	    public String getDisplayName() {
127	        return this.getLastName() + ", " + this.getFirstName();
128	    }
129	
130	    /**
131	     * The owner's initials: the upper-cased first letters of the first and last name,
132	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
133	     */
134	    @Transient
135	    public String getInitials() {
136	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
137	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
138	    }
139	
140	    protected Set<Pet> getPetsInternal() {
141	        if (this.pets == null) {
142	            this.pets = new HashSet<>();
143	        }
144	        return this.pets;
145	    }
146	
147	    protected void setPetsInternal(Set<Pet> pets) {
148	        this.pets = pets;
149	    }
150	
151	    public List<Pet> getPets() {
152	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
153	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
154	        return Collections.unmodifiableList(sortedPets);
155	    }
156	
157	    public void setPets(List<Pet> pets) {
158	        this.pets = new HashSet<>(pets);
159	    }
160	
161	    public void addPet(Pet pet) {
162	        getPetsInternal().add(pet);
163	        pet.setOwner(this);
164	    }
165	
166	    /**
167	     * Return the Pet with the given name, or null if none found for this Owner.
168	     *
169	     * @param name to test
170	     * @return true if pet name is already in use
171	     */
172	    public Pet getPet(String name) {
173	        return getPet(name, false);
174	    }
175	
176	    /**
177	     * Return the Pet with the given name, or null if none found for this Owner.
178	     *
179	     * @param name to test
180	     * @return true if pet name is already in use
181	     */
182	    public Pet getPet(String name, boolean ignoreNew) {
183	        name = name.toLowerCase();
184	        for (Pet pet : getPetsInternal()) {
185	            if (!ignoreNew || !pet.isNew()) {
186	                String compName = pet.getName();
187	                compName = compName.toLowerCase();
188	                if (compName.equals(name)) {
189	                    return pet;
190	                }
191	            }
192	        }
193	        return null;
194	    }
195	
196	    public Pet getPet(Integer petId) {
197	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
198	    }
199	
200	    @Override
201	    public String toString() {
202	        return new ToStringCreator(this)
203	
204	            .append("id", this.getId())
205	            .append("new", this.isNew())
206	            .append("lastName", this.getLastName())
207	            .append("firstName", this.getFirstName())
208	            .append("address", this.address)
209	            .append("city", this.city)
210	            .append("telephone", this.telephone)
211	            .toString();
212	    }
213	}
